def keep_new_rows(g):
    """Keep every row that differs from the row above it (the first row is always kept)."""
    return [row for i, row in enumerate(g) if i == 0 or row != g[i-1]]
def transpose(g):
    """Mirror the grid across its main diagonal."""
    return [list(r) for r in zip(*g)]
def dedup_runs(g):
    """Keep rows and columns that differ from their predecessor (collapse runs of identical rows/columns)."""
    return transpose(keep_new_rows(transpose(keep_new_rows(g))))

